## Scales data between ranges. With just one arg the range is between 0 and 1.def scaleToRange(values, newMin=0, newMax=1):			newValues	= []	oldMin	= min(values)	oldMax	= max(values)	oldRange	= (oldMax*1.0) - oldMin	newRange	= newMax - newMin	ratio	= newRange/oldRange		for x in values:		scaling = ((x-oldMin) * ratio + newMin)		newValues.append(scaling)	return newValues